      "id": "AHC001",
      "theme": "history",
      "concept": "h-chronologie",
      "type": "scenario",
      "official": false,
      "prompt": "Une frise présente « 1789 : la France devient une République qui ne sera plus jamais interrompue ». Quelle correction faut-il apporter ?",
      "correct": "La République commence en 1792 et la France connaît ensuite d’autres monarchies et empires.",
      "wrong": [
        "La Première République commence en 1789 et dure jusqu’en 1958.",
        "Les deux empires précèdent tous deux la Révolution de 1789.",
        "Le régime de Vichy constitue une sixième République démocratique."
      ],
      "explanation": "La Révolution, la Première République et les cinq régimes républicains ne sont pas une période unique. La chronologie comprend aussi des retours monarchiques et deux empires.",
      "hook": "Révolution en 1789 ne signifie pas République ininterrompue.",
      "wrongReasons": {
        "La Première République commence en 1789 et dure jusqu’en 1958.": "La Révolution débute en 1789, mais la République naît en 1792 et connaît plusieurs interruptions.",
        "Les deux empires précèdent tous deux la Révolution de 1789.": "Le Premier et le Second Empire sont postérieurs à 1789.",
        "Le régime de Vichy constitue une sixième République démocratique.": "Vichy rompt avec la République et instaure un régime autoritaire, pas une république démocratique."
      },
      "sourceIds": [
        "HS01",
        "livret-histoire-periodes"
      ],
      "depth": "essentiel",
      "level": "essentiel",
      "factIds": [
        "AHC-F001"
      ]
